floor_fn:
"""
    Return a unified diff string between strings `a` and `b`.

    :param a: The first string (e.g. before).
    :param b: The second string (e.g. after).
    :param a_name: The "filename" to display for the `a` string.
    :param b_name: The "filename" to display for the `b` string.
    :return: A `git diff` like diff of the two strings.
    """
def unified_diff(a: str, b: str, a_name: str, b_name: str) -> str {
    import difflib;
    a_lines = [(line + "\n") for line in a.split("\n")];
    b_lines = [(line + "\n") for line in b.split("\n")];
    return "".join(
        difflib.unified_diff(a_lines, b_lines, fromfile=a_name, tofile=b_name, n=5)
    );
}

test_blocks:
test "t0" {
    assert (
        unified_diff("abc", "def", "a.txt", "b.txt")
        == """--- a.txt
+++ b.txt
@@ -1 +1 @@
-abc
+def
"""
    );;
}

test "t1" {
    assert (
        unified_diff("a\nb\nc", "a\nc\nd", "a.txt", "b.txt")
        == "--- a.txt\n+++ b.txt\n@@ -1,3 +1,3 @@\n a\n-b\n c\n+d\n"
    );;
}

test "t2" {
    assert (
        unified_diff("Hello\nWorld", "Hello\nGalaxy", "before", "after")
        == """--- before
+++ after
@@ -1,2 +1,2 @@
 Hello
-World
+Galaxy
"""
    );;
}

test "t3" {
    assert (
        unified_diff("a\nb\nc", "a\nb\nd\ne\nf", "a", "b")
        == """\
--- a
+++ b
@@ -1,3 +1,5 @@
 a
 b
-c
+d
+e
+f
"""
    );;
}

test "t4" {
    assert (unified_diff("a\nb\nc\nd\ne", "a\nb\nc\nd\ne", "a", "a") == "");;
}
